"""Recompute scoped GPU timing statistics from an explicit instrumented run."""
import argparse,json,statistics,math
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--run',type=Path,default=Path('evidence/gpu-timing-run.json'));p.add_argument('--output',type=Path,default=Path('evidence/gpu-timing-summary.json'));a=p.parse_args();r=json.loads(a.run.read_text());samples=[s for s in r['gpuTiming'] if s['present']>=600]
